-- 50 new products across 8 categories -- see V13 for the category column itself.
-- Category counts: Electronics 6, Home & Kitchen 7, Sports & Outdoors 6, Books 7,
-- Fashion 7, Toys & Games 6, Beauty 6, Office 5 (50 total, ids 8-57).

-- Explicit ids above never advance product_seq on their own -- same fix as
-- V3__fix_sequences_after_seed_data.sql and V5__add_more_products.sql, needed again for
-- the same reason each time: an explicit-id INSERT and a sequence are two entirely
-- separate mechanisms that don't know about each other unless told to.
SELECT setval('product_seq', (SELECT COALESCE(MAX(id), 1) FROM product));
